{"cards": [{"node_code": "N_7e5ade0d5671cc0d", "definition": "聚焦单一机场日常运行组织、流程控制、安全服务协调及应急响应的管理学科分支，旨在保障机场高效、安全、有序运转。", "boundary": "本节点侧重机场内部微观运行层面的组织与调度。边界在于区分“运行管理”与“设施工程”（物理建设归入场道或建筑物）、“运行管理”与“空域管制”（空中飞行指挥归入空中管制与飞行调度）。若涉及多机场宏观资源分配或设施长期维护策略，应分别归入机场群协同管理或全寿命管理。", "includes": ["机场日常运行流程、航班地面保障协调", "机场安全管理、服务质量控制及突发事件应急处置", "机场运行指标监控、绩效考核及运行效率优化"], "excludes": ["机场跑道、航站楼等物理设施的设计与施工", "空中交通管制指令发布与空域流量管理", "机场设施长期维护、更新改造及全寿命周期成本分析"], "sibling_distinctions": [{"other_code": "N_a99a405e56fd3c22", "rule": "本节点关注单一机场内部的运行组织与效率；机场群协同管理关注多个机场间的宏观资源分配、功能定位及区域协调。"}, {"other_code": "N_d6ef7f2d39f171f3", "rule": "本节点关注日常运行状态下的管理与控制；机场设施全寿命管理关注设施从规划、建设到退役全周期的技术状态与经济性管理。"}], "cross_boundary_rule": "涉及机场运行数据时，若用于实时调度与流程优化，归入本节点；若用于设施长期性能评估或投资决策，归入机场设施全寿命管理。"}, {"node_code": "N_a99a405e56fd3c22", "definition": "研究区域内多个机场在功能定位、空域资源、地面交通及运营服务等方面的协调机制与宏观管理策略的学科分支。", "boundary": "本节点聚焦于多机场系统层面的宏观协同。边界在于区分“机场群协同”与“单机场运行”（单一机场内部流程归入机场运行管理）、“机场群协同”与“综合运输”（侧重航空内部协调，若涉及铁公航多式联运衔接则归入综合运输）。若仅涉及单个机场的扩建规划，归入机场规划与设计。", "includes": ["机场群功能定位、分工协作及区域航空网络优化", "多机场空域资源协调、地面交通衔接及信息共享机制", "机场群整体运行效率评估、政策制定及宏观管理策略"], "excludes": ["单一机场内部的日常运行调度与流程管理", "单个机场的物理设施规划、设计与建设", "跨运输方式（如铁路、公路）的综合联运组织"], "sibling_distinctions": [{"other_code": "N_7e5ade0d5671cc0d", "rule": "本节点关注多机场间的宏观协调与系统优化；机场运行管理关注单一机场内部的微观运行组织与效率。"}, {"other_code": "N_e467c6be89889de3", "rule": "本节点侧重多机场系统的宏观布局与协同策略；机场规划与设计侧重单个机场的物理空间布局、设施配置及工程方案。"}], "cross_boundary_rule": "涉及机场间协调时，若侧重航空系统内部资源分配与功能互补，归入本节点；若侧重与铁路、公路等其他运输方式的衔接换乘，需视树中是否有综合运输节点，若有则归入综合运输。"}, {"node_code": "N_d6ef7f2d39f171f3", "definition": "涵盖机场设施从规划、建设、运营维护到更新改造及退役处置全生命周期的技术状态监测、性能评估与经济管理的学科分支。", "boundary": "本节点聚焦于设施资产的全周期技术管理与经济性分析。边界在于区分“全寿命管理”与“日常运行”（日常航班保障归入机场运行管理）、“全寿命管理”与“工程建设”（具体施工技术与设计归入场道或建筑物）。若仅涉及设施日常维修操作，归入运行管理或相应设备维护；若涉及长期性能退化预测与更新决策，归入本节点。", "includes": ["机场设施性能监测、状态评估及健康管理系统", "设施维护策略、更新改造决策及全寿命周期成本分析", "机场设施退役处置、资产价值评估及可持续性管理"], "excludes": ["机场日常航班运行调度、旅客服务流程管理", "机场跑道、航站楼等具体工程的设计方案与施工技术", "空中交通管制系统与空域资源管理"], "sibling_distinctions": [{"other_code": "N_7e5ade0d5671cc0d", "rule": "本节点关注设施资产的全周期技术状态与经济性；机场运行管理关注日常运行流程、安全服务及应急协调。"}, {"other_code": "N_39d02e3030f41feb", "rule": "本节点关注设施全周期的性能评估与维护决策；机场场道工程关注跑道、滑行道等具体工程的设计、施工技术与材料应用。"}], "cross_boundary_rule": "涉及设施维护时，若侧重日常操作与即时故障处理，归入机场运行管理或地面设备；若侧重长期性能退化预测、更新改造投资分析及全寿命成本优化，归入本节点。"}]}
